import pandas as pd

def clean(df):
    allowed_species = ["Adelie", "Chinstrap", "Gentoo"]
    allowed_islands = ["Biscoe", "Dream", "Torgersen"]

    species_ok = df["species"].isin(allowed_species)
    island_ok = df["island"].str.strip().isin(allowed_islands)
    body_ok = (df["body_mass_g"].notna() 
               ) & (df["body_mass_g"].ge(2500) 
               ) & (df["body_mass_g"].le(6500))

    valid_df = df[species_ok & island_ok & body_ok]
    return valid_df

def answer(df):
    grouped = df.groupby("species")["body_mass_g"].mean()
    return {species: avg for species, avg in grouped.items()}
